# Try filling regions based on proximity to all points
grid_h, grid_w = 25, 19

points_with_val = [
    ((0, 16), 6), ((2, 13), 6), ((3, 1), 5), ((9, 6), 5),
    ((5, 11), 9), ((6, 17), 9), ((7, 11), 7), ((13, 9), 7),
    ((12, 2), 1), ((16, 3), 1), ((13, 17), 3), ((19, 15), 3),
    ((14, 10), 2), ((18, 9), 2), ((15, 4), 4), ((21, 8), 4),
]

# Try 1: Fill based on proximity
for dist_threshold in [3, 5, 8]:
    output = [[0] * grid_w for _ in range(grid_h)]
    for (r, c), val in points_with_val:
        for dr in range(-dist_threshold, dist_threshold+1):
            for dc in range(-dist_threshold, dist_threshold+1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < grid_h and 0 <= cc < grid_w:
                    output[rr][cc] = val
    print(f"\nDistance threshold {dist_threshold}:")
    nonzero = sum(sum(row) for row in output)
    print(f"  Non-zero cells: {nonzero}")
    # print a few rows
    for r in [5, 10, 15, 20]:
        print(f'  {r}:', ' '.join(str(output[r][c]) for c in range(grid_w))[:60])
